<?php
 namespace QQWorld\Search\Model\Adminhtml\System\Config\Source; class EngineTest extends \PHPUnit\Framework\TestCase { protected $_model; protected function setUp() { parent::setUp(); $this->_model = \QQWorld\TestFramework\Helper\Bootstrap::getObjectManager()->create( \QQWorld\Search\Model\Adminhtml\System\Config\Source\Engine::class ); } public function testToOptionArray() { $options = $this->_model->toOptionArray(); $this->assertNotEmpty($options); foreach ($options as $option) { $this->assertArrayHasKey('label', $option); $this->assertArrayHasKey('value', $option); } } } 